import { useEffect, useState } from 'react'
import type { PageInventory } from '../../../shared/pnw/page-types.ts'

let loading: Promise<Record<string, PageInventory>> | null = null

/**
 * src/data/page-inventory.ts (generated by scripts/page-inventory.ts) is
 * ~230 KB that only the Szerkesztő needs, so it is a lazy chunk of its own -
 * see vite.config.ts - fetched the first time an editor screen asks for it.
 */
export function loadInventory(): Promise<Record<string, PageInventory>> {
  loading ??= import('../../data/page-inventory.ts').then((module) => module.pageInventory)
  return loading
}

export function useInventory(): Record<string, PageInventory> | null {
  const [inventory, setInventory] = useState<Record<string, PageInventory> | null>(null)

  useEffect(() => {
    let cancelled = false
    loadInventory().then((loaded) => {
      if (!cancelled) setInventory(loaded)
    })
    return () => {
      cancelled = true
    }
  }, [])

  return inventory
}
